<?php
// LuminaDB friendly error page. Loaded before every PHP file through php.ini's auto_prepend_file.
// Generated by LuminaDB at every start: don't edit, it is rewritten next time.
// Fatal errors and uncaught exceptions get a full page with the file, the line, the code around it and a plain
// explanation. Warnings and notices get a strip at the bottom of the page. JSON requests get a JSON error.
// Everything is also written to logs\projects\<project>-php.log, which LuminaDB shows live.
if (PHP_SAPI === 'cli' || defined('LUMINA_ERRORS')) {
    return;
}
// Only students' projects get the error page: phpMyAdmin and anything else outside projects\ handle their own errors.
if (stripos(str_replace('\\', '/', isset($_SERVER['SCRIPT_FILENAME']) ? $_SERVER['SCRIPT_FILENAME'] : ''),
            rtrim(str_replace('\\', '/', '__PROJECTS__'), '/') . '/') !== 0) {
    return;
}
define('LUMINA_ERRORS', 1);

final class LuminaErrors
{
    const PROJECTS = '__PROJECTS__';
    const LOGS = '__LOGS__';
    const DB_PORT = '__DBPORT__';
    const FATAL = 4437; // E_ERROR | E_PARSE | E_CORE_ERROR | E_COMPILE_ERROR | E_USER_ERROR | E_RECOVERABLE_ERROR

    public static $warnings = array();
    public static $shown = false;
    private static $project = null;

    public static function install()
    {
        set_error_handler(array(__CLASS__, 'onError'));
        set_exception_handler(array(__CLASS__, 'onException'));
        register_shutdown_function(array(__CLASS__, 'onShutdown'));
    }

    /** The project the running script belongs to: the first folder under projects\. */
    public static function project()
    {
        if (self::$project !== null) {
            return self::$project;
        }
        $script = isset($_SERVER['SCRIPT_FILENAME']) ? str_replace('\\', '/', $_SERVER['SCRIPT_FILENAME']) : '';
        $root = rtrim(str_replace('\\', '/', self::PROJECTS), '/') . '/';
        self::$project = '';
        if ($script !== '' && stripos($script, $root) === 0) {
            $rest = substr($script, strlen($root));
            $slash = strpos($rest, '/');
            self::$project = $slash === false ? '' : substr($rest, 0, $slash);
        }
        return self::$project;
    }

    public static function onError($type, $message, $file = '', $line = 0)
    {
        // Respect error_reporting() and the @ operator.
        if (!(error_reporting() & $type)) {
            return false;
        }
        $kind = self::typeName($type);
        self::log($kind, $message, $file, $line);
        if ($type & (E_USER_ERROR | E_RECOVERABLE_ERROR)) {
            self::show('Error', $message, $file, $line, array_slice(debug_backtrace(), 1));
            exit(255);
        }
        if (count(self::$warnings) < 50) {
            self::$warnings[] = array('kind' => $kind, 'message' => $message, 'file' => $file, 'line' => $line);
        }
        return true;
    }

    public static function onException($e)
    {
        $kind = 'Uncaught ' . get_class($e);
        self::log($kind, $e->getMessage(), $e->getFile(), $e->getLine());
        self::show($kind, $e->getMessage(), $e->getFile(), $e->getLine(), $e->getTrace());
    }

    public static function onShutdown()
    {
        $last = error_get_last();
        if ($last !== null && ($last['type'] & self::FATAL) && !self::$shown) {
            $kind = 'Fatal error';
            if ($last['type'] === E_PARSE) {
                $kind = 'Syntax error';
            }
            $message = $last['message'];
            // PHP puts the stack of a fatal error inside the message; keep only the first line.
            $cut = strpos($message, "\nStack trace:");
            if ($cut !== false) {
                $message = substr($message, 0, $cut);
            }
            if (preg_match('/^Uncaught (\w[\w\\\\]*): (.*) in [A-Za-z]:.*$/s', $message, $m)) {
                $kind = 'Uncaught ' . $m[1];
                $message = $m[2];
            }
            self::log($kind, $message, $last['file'], $last['line']);
            self::show($kind, $message, $last['file'], $last['line'], array());
            return;
        }
        if (self::$warnings && !self::$shown && !self::wantsJson() && self::isHtmlResponse()) {
            echo self::strip();
        }
    }

    // ------------------------------------------------------------------ output

    private static function show($kind, $message, $file, $line, $trace)
    {
        self::$shown = true;
        $headersSent = headers_sent();
        if (!$headersSent) {
            while (ob_get_level() > 0) {
                ob_end_clean();
            }
            http_response_code(500);
        }
        $hint = self::explain($message);
        if (!self::isLocal()) {
            // Demo mode: someone on the network is looking. Never show code or paths to them.
            if (!$headersSent) {
                header('Content-Type: text/html; charset=UTF-8');
            }
            echo '<!doctype html><meta charset="utf-8"><title>Something went wrong</title>'
                . '<body style="font:16px/1.5 Segoe UI,sans-serif;background:#F2EDE1;color:#1C1A16;padding:48px">'
                . '<h1 style="font-weight:600">Something went wrong on this page.</h1>'
                . '<p>The details are on the presenter\'s PC, in LuminaDB.</p></body>';
            return;
        }
        if (self::wantsJson()) {
            if (!$headersSent) {
                header('Content-Type: application/json; charset=UTF-8');
            }
            echo json_encode(array('error' => array(
                'type' => $kind,
                'message' => $message,
                'file' => self::shortPath($file),
                'line' => $line,
                'explanation' => $hint,
            )), JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PARTIAL_OUTPUT_ON_ERROR);
            return;
        }
        if (!$headersSent) {
            header('Content-Type: text/html; charset=UTF-8');
        }
        echo self::page($kind, $message, $file, $line, $trace, $hint);
    }

    private static function page($kind, $message, $file, $line, $trace, $hint)
    {
        $h = function ($s) { return htmlspecialchars((string)$s, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); };
        // When the error is inside vendor\ or LuminaDB itself, point at the first line of the project's own code too.
        $yours = null;
        if (self::isLibrary($file)) {
            foreach ($trace as $f) {
                if (isset($f['file']) && !self::isLibrary($f['file'])) {
                    $yours = $f;
                    break;
                }
            }
        }
        $out = self::head('PHP error') . '<main>';
        $out .= '<p class="kicker">' . $h($kind) . (self::project() !== '' ? ' &middot; ' . $h(self::project()) : '') . '</p>';
        $out .= '<h1>' . $h($message) . '</h1>';
        $out .= '<p class="where"><span class="file">' . $h(self::shortPath($file)) . '</span> line <b>' . (int)$line . '</b></p>';
        if ($hint !== null) {
            $out .= '<div class="hint"><span class="label">What it means</span><p>' . $h($hint) . '</p></div>';
        }
        $out .= self::excerpt($file, $line);
        if ($yours !== null) {
            $out .= '<p class="where">Called from your code: <span class="file">' . $h(self::shortPath($yours['file'])) . '</span> line <b>' . (int)$yours['line'] . '</b></p>';
            $out .= self::excerpt($yours['file'], $yours['line']);
        }
        if ($trace) {
            $out .= '<details><summary>Stack (' . count($trace) . ' calls)</summary><ol>';
            foreach ($trace as $f) {
                $fn = (isset($f['class']) ? $f['class'] . $f['type'] : '') . (isset($f['function']) ? $f['function'] : '?') . '()';
                $at = isset($f['file']) ? self::shortPath($f['file']) . ':' . (isset($f['line']) ? $f['line'] : '?') : '(PHP)';
                $out .= '<li><code>' . $h($fn) . '</code> <span class="file">' . $h($at) . '</span></li>';
            }
            $out .= '</ol></details>';
        }
        if (self::$warnings) {
            $out .= self::warningList();
        }
        $out .= '<p class="foot">Shown by LuminaDB because PHP stopped. Only you can see this page; the full log is in LuminaDB under Projects &rsaquo; Logs.</p>';
        return $out . '</main></body></html>';
    }

    private static function strip()
    {
        $n = count(self::$warnings);
        return self::style() . '<div id="lumina-warnings"><details' . ($n <= 3 ? ' open' : '') . '><summary>PHP reported '
            . $n . ($n === 1 ? ' problem' : ' problems') . ' on this page. The page still ran.</summary>'
            . self::warningList() . '</details></div>';
    }

    private static function warningList()
    {
        $h = function ($s) { return htmlspecialchars((string)$s, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); };
        $out = '<ul class="warnings">';
        foreach (self::$warnings as $w) {
            $hint = self::explain($w['message']);
            $out .= '<li><span class="tag">' . $h($w['kind']) . '</span> ' . $h($w['message'])
                . ' <span class="file">' . $h(self::shortPath($w['file'])) . ':' . (int)$w['line'] . '</span>'
                . ($hint !== null ? '<br><span class="small">' . $h($hint) . '</span>' : '') . '</li>';
        }
        return $out . '</ul>';
    }

    private static function excerpt($file, $line)
    {
        if (!is_string($file) || $file === '' || !is_file($file) || filesize($file) > 2000000) {
            return '';
        }
        $lines = @file($file, FILE_IGNORE_NEW_LINES);
        if (!$lines) {
            return '';
        }
        $from = max(1, $line - 6);
        $to = min(count($lines), $line + 4);
        $out = '<pre class="code">';
        for ($i = $from; $i <= $to; $i++) {
            $text = htmlspecialchars(str_replace("\t", '    ', $lines[$i - 1]), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
            $out .= '<span class="ln' . ($i === (int)$line ? ' hit' : '') . '"><i>' . $i . '</i>' . ($text === '' ? ' ' : $text) . '</span>';
        }
        return $out . '</pre>';
    }

    private static function head($title)
    {
        return "<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">"
            . '<title>' . $title . '</title>' . self::style() . '</head><body class="lumina-page">';
    }

    private static function style()
    {
        return '<style>'
            . 'body.lumina-page{margin:0;background:#F2EDE1;color:#1C1A16;font:15px/1.55 "IBM Plex Sans","Segoe UI",sans-serif}'
            . '.lumina-page main{max-width:960px;margin:0 auto;padding:40px 24px 64px}'
            . '.lumina-page .kicker{margin:0 0 8px;font:600 12px/1 "IBM Plex Mono",Consolas,monospace;letter-spacing:.08em;text-transform:uppercase;color:#D83A1E}'
            . '.lumina-page h1{margin:0 0 12px;font:600 26px/1.25 "Bricolage Grotesque","Segoe UI",sans-serif;overflow-wrap:anywhere}'
            . '.lumina-page .where{margin:0 0 16px;color:#4A453B}'
            . '#lumina-warnings .file,.lumina-page .file{font-family:"IBM Plex Mono",Consolas,monospace;font-size:13px;color:#4A453B;overflow-wrap:anywhere}'
            . '.lumina-page .hint{border-left:3px solid #1F3FBF;background:#E1E5F5;padding:12px 16px;margin:0 0 20px}'
            . '.lumina-page .hint .label{display:block;font:600 11px/1 "IBM Plex Mono",Consolas,monospace;letter-spacing:.08em;text-transform:uppercase;color:#1F3FBF;margin-bottom:6px}'
            . '.lumina-page .hint p{margin:0}'
            . '.lumina-page pre.code{background:#FBF8F1;border:1px solid #D8CFBC;margin:0 0 20px;padding:8px 0;overflow-x:auto;font:13px/1.6 "IBM Plex Mono",Consolas,monospace}'
            . '.lumina-page .ln{display:block;padding:0 16px 0 0;white-space:pre}'
            . '.lumina-page .ln i{display:inline-block;width:48px;padding-right:12px;text-align:right;font-style:normal;color:#857D6C;user-select:none}'
            . '.lumina-page .ln.hit{background:#F7DDD3;box-shadow:inset 3px 0 #D83A1E}'
            . '.lumina-page .ln.hit i{color:#D83A1E;font-weight:600}'
            . '.lumina-page details{margin:0 0 20px}.lumina-page summary{cursor:pointer;color:#1F3FBF}'
            . '.lumina-page ol{font-size:13px;padding-left:28px}.lumina-page code{font-family:"IBM Plex Mono",Consolas,monospace}'
            . '.lumina-page .foot{margin-top:32px;border-top:1px solid #D8CFBC;padding-top:12px;color:#857D6C;font-size:13px}'
            . '#lumina-warnings{all:initial;display:block;margin:24px 0 0;background:#F4E6C6;border-top:3px solid #B8730A;color:#1C1A16;font:14px/1.5 "IBM Plex Sans","Segoe UI",sans-serif;padding:10px 16px}'
            . '#lumina-warnings summary{cursor:pointer;font-weight:600}'
            . '.warnings{margin:8px 0 0;padding-left:20px}.warnings li{margin:0 0 6px}'
            . '.warnings .tag{font:600 11px/1 "IBM Plex Mono",Consolas,monospace;text-transform:uppercase;color:#B8730A}'
            . '.warnings .small{color:#4A453B;font-size:13px}'
            . '</style>';
    }

    // ------------------------------------------------------------------ helpers

    private static function wantsJson()
    {
        foreach (headers_list() as $hdr) {
            if (stripos($hdr, 'content-type:') === 0) {
                return stripos($hdr, 'json') !== false;
            }
        }
        $accept = isset($_SERVER['HTTP_ACCEPT']) ? $_SERVER['HTTP_ACCEPT'] : '';
        if (stripos($accept, 'application/json') !== false && stripos($accept, 'text/html') === false) {
            return true;
        }
        $xhr = isset($_SERVER['HTTP_X_REQUESTED_WITH']) ? $_SERVER['HTTP_X_REQUESTED_WITH'] : '';
        return strcasecmp($xhr, 'XMLHttpRequest') === 0;
    }

    private static function isHtmlResponse()
    {
        foreach (headers_list() as $hdr) {
            if (stripos($hdr, 'content-type:') === 0) {
                return stripos($hdr, 'text/html') !== false;
            }
            if (stripos($hdr, 'location:') === 0) {
                return false;
            }
        }
        return true;
    }

    private static function isLocal()
    {
        // The demo-mode site adds this header (and the local sites remove it), so Apache projects behind the
        // proxy, whose REMOTE_ADDR is always 127.0.0.1, are recognised too.
        if (!empty($_SERVER['HTTP_X_LUMINA_DEMO'])) {
            return false;
        }
        $ip = isset($_SERVER['REMOTE_ADDR']) ? $_SERVER['REMOTE_ADDR'] : '127.0.0.1';
        return $ip === '127.0.0.1' || $ip === '::1' || strpos($ip, '127.') === 0;
    }

    private static function isLibrary($file)
    {
        $f = str_replace('\\', '/', (string)$file);
        return stripos($f, '/vendor/') !== false || stripos($f, '/lumina/prepend.php') !== false;
    }

    private static function shortPath($file)
    {
        $f = str_replace('\\', '/', (string)$file);
        $root = rtrim(str_replace('\\', '/', self::PROJECTS), '/') . '/';
        return stripos($f, $root) === 0 ? substr($f, strlen($root)) : $f;
    }

    private static function typeName($type)
    {
        switch ($type) {
            case E_WARNING: case E_USER_WARNING: case E_CORE_WARNING: case E_COMPILE_WARNING: return 'Warning';
            case E_NOTICE: case E_USER_NOTICE: return 'Notice';
            case E_DEPRECATED: case E_USER_DEPRECATED: return 'Deprecated';
            case E_RECOVERABLE_ERROR: case E_USER_ERROR: return 'Error';
            default: return 'Problem';
        }
    }

    private static function log($kind, $message, $file, $line)
    {
        $name = self::project();
        $target = rtrim(self::LOGS, '\\/') . DIRECTORY_SEPARATOR . ($name !== '' ? $name : '_other') . '-php.log';
        $uri = isset($_SERVER['REQUEST_URI']) ? $_SERVER['REQUEST_URI'] : '';
        $entry = '[' . date('Y-m-d H:i:s') . '] ' . $kind . ': ' . str_replace(array("\r", "\n"), ' ', $message)
            . ' in ' . self::shortPath($file) . ':' . $line . ($uri !== '' ? ' (' . $uri . ')' : '') . PHP_EOL;
        @file_put_contents($target, $entry, FILE_APPEND | LOCK_EX);
    }

    /** A plain-English explanation for the common messages, or null. */
    public static function explain($message)
    {
        $m = (string)$message;
        $rules = array(
            '/Undefined variable \$(\w+)/' =>
                '$%1 is used before it was given a value on this path. Check the spelling, or set it first (for example $%1 = \'\';).',
            '/Undefined array key "([^"]*)"/' =>
                'The array has no item called "%1". If it comes from a form, the field is missing or named differently: use $_POST[\'%1\'] ?? \'\' to allow for that.',
            '/Undefined array key (-?\d+)/' =>
                'The array has no item number %1. Arrays start at 0; check the count before reading it.',
            '/Call to undefined function (mysql_\w+)\(\)/' =>
                '%1() was removed in PHP 7. Use mysqli_ functions (they take the connection as the first argument) or PDO.',
            '/Call to undefined function (\w+)\(\)/' =>
                'PHP has no function called %1(). Check the spelling, or the file that defines it was not included (require_once).',
            '/Call to a member function (\w+)\(\) on (null|bool|false)/' =>
                'You called ->%1() on %2: the thing before the arrow was never created. Usually a query, a fetch or a connection failed earlier; check its result first.',
            '/Trying to access array offset on (?:value of type )?(null|bool|false)/' =>
                'The variable is %1, not an array. Often a fetch that found no row; check the result before reading from it.',
            "/Access denied for user '([^']*)'@'([^']*)'/" =>
                'MariaDB refused the user name or password for "%1". Use the details in your project\'s config.php; LuminaDB shows them under Projects > Overview.',
            "/Unknown database '([^']*)'/" =>
                'There is no database called %1. Create it in LuminaDB, or fix the name in config.php.',
            "/Table '([^']*)' doesn't exist/" =>
                'There is no table %1. Check the spelling, or import the .sql file that creates it.',
            "/Unknown column '([^']*)' in '([^']*)'/" =>
                'The query mentions a column %1 that the table doesn\'t have. Check the spelling against the table in LuminaDB > Tables.',
            '/(No connection could be made|Connection refused|actively refused|php_network_getaddresses|getaddrinfo)/' =>
                'PHP couldn\'t reach MariaDB. Start it from LuminaDB; it listens on 127.0.0.1 port ' . self::DB_PORT . '.',
            '/MySQL server has gone away/' =>
                'The database connection was closed. Keep the connection in a variable for as long as you use its statements, and avoid very long pauses.',
            '/You have an error in your SQL syntax.*?near \'(.{0,60})/s' =>
                'MariaDB couldn\'t read the query just before "%1". Paste the query into the LuminaDB Notebook to see the exact spot.',
            "/Duplicate entry '([^']*)' for key '([^']*)'/" =>
                'A row with "%1" already exists and %2 must be unique. Check first, or update the existing row instead.',
            "/Field '([^']*)' doesn't have a default value/" =>
                'The INSERT leaves out %1, which has no default. Give it a value, or a default in Tables > Structure.',
            "/Data too long for column '([^']*)'/" =>
                'The value is longer than column %1 allows. Shorten it or make the column bigger in Tables > Structure.',
            "/Incorrect (\w+) value: '([^']*)' for column/" =>
                '"%2" is not a valid %1 for that column. Dates must look like 2026-11-24.',
            '/foreign key constraint fails/' =>
                'The row points at a parent row that doesn\'t exist (or still has children). Insert the parent first, or delete the children first.',
            '/headers already sent by \(output started at (.+):(\d+)\)/' =>
                'Something was printed before header(), setcookie() or session_start(). Output started at %1 line %2: often a space or blank line before <?php, or an echo.',
            '/headers already sent/' =>
                'Something was printed before header(), setcookie() or session_start(). Move those calls above any echo or HTML.',
            '/Failed to open stream: No such file or directory|Failed opening required/' =>
                'PHP can\'t find that file. Paths are relative to the page being run; build them from __DIR__, for example require __DIR__ . \'/config.php\';',
            '/Class "([^"]+)" not found/' =>
                'PHP doesn\'t know the class %1. A require is missing, or Composer\'s autoloader: add require __DIR__ . \'/vendor/autoload.php\'; or run composer install.',
            '/syntax error, unexpected (.+?)(,|$)/' =>
                'PHP couldn\'t read this line (unexpected %1). Look for a missing ; ) } or quote on this line or the one before.',
            '/Maximum execution time of (\d+) seconds? exceeded/' =>
                'The page ran for more than %1 seconds: a loop that never ends, or a very slow query. If the work is real, raise the time limit in PHP settings.',
            '/Allowed memory size of (\d+) bytes exhausted/' =>
                'The page used all the memory PHP allows. Often a loop that keeps adding to an array, or loading a huge result at once. Raise the memory limit in PHP settings if it is real.',
            '/Division by zero/' =>
                'A number was divided by 0. Check the divisor first, for example if ($count > 0).',
            '/Array to string conversion/' =>
                'An array was used as text (in echo or a string). Use print_r($x), implode(), or pick one item.',
            '/must be of type (\S+), (\S+) given/' =>
                'A function got a %2 where it needs %1. Check what the variable holds before passing it (var_dump helps).',
            '/Unsupported operand types/' =>
                'The calculation mixes types that can\'t be combined, such as an array and a number.',
            '/Cannot redeclare (\S+)/' =>
                '%1 is defined twice, usually because a file is included twice. Use require_once instead of require.',
        );
        foreach ($rules as $pattern => $text) {
            if (preg_match($pattern, $m, $g)) {
                return preg_replace_callback('/%(\d)/', function ($x) use ($g) {
                    return isset($g[(int)$x[1]]) ? trim($g[(int)$x[1]], "\"' ") : '';
                }, $text);
            }
        }
        return null;
    }
}

LuminaErrors::install();
